package template

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

// SubscriptionRecord is the committed trace of one message-ref parameter's
// resolution: which registry message the component subscribes to, pinned to
// the schema version that was the registry's default at scaffold time. It
// travels in the scaffold record so later commands can compare what the
// component was scaffolded against with what the registry now declares.
type SubscriptionRecord struct {
	// Parameter is the message-ref template parameter that held the
	// reference.
	Parameter string `json:"parameter"`
	// Message is the message's full xid — unambiguous where a bare message
	// id is not.
	Message string `json:"message"`
	// SchemaID and SchemaVersion come from the schema resource the
	// message's dataschemaxid pointed at. Empty when that reference dangles
	// — the registry keeps unresolved references with a warning, and the
	// record mirrors what the registry actually said.
	SchemaID      string `json:"schemaid,omitempty"`
	SchemaVersion string `json:"schemaVersion,omitempty"`
}

// messageRefFields returns the template's message-ref parameters in
// declaration order.
func messageRefFields(t *Template) []FieldSpec {
	var refs []FieldSpec
	for _, f := range t.Fields() {
		if f.MessageRef {
			refs = append(refs, f)
		}
	}
	return refs
}

// fetchMessageRegistry builds a client for opts and fetches the export
// document. It runs only when the template declares a message-ref
// parameter — templates without one never touch the network for this.
func fetchMessageRegistry(ctx context.Context, opts CreateOptions) (*xregistry.Export, error) {
	client, err := xregistry.NewClient(opts.RegistryURL, xregistry.WithUserAgent(opts.UserAgent))
	if err != nil {
		return nil, err
	}
	doc, err := client.Export(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve message reference: %w", err)
	}
	return doc, nil
}

// errNoRegistryConfigured reports a message-ref value that cannot be
// validated because no registry is configured. It is only ever returned
// when a reference was actually given — a template that merely offers the
// parameter must not demand a registry from users who wire by hand.
var errNoRegistryConfigured = errors.New("template declares a message registry reference but no registry is configured\npass --registry-url, set INTROPY_REGISTRY_URL, or add registryUrl to the config file")

// messageRefValuePresent reports whether any message-ref parameter ended
// up with a value — the condition under which the registry is mandatory
// rather than a suggestion source.
func messageRefValuePresent(refs []FieldSpec, values map[string]any) bool {
	for _, f := range refs {
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			return true
		}
	}
	return false
}

// messageRefPrompter wraps the create prompter so a message-ref parameter
// prompts with the registry's message ids as its pick list. The prompt is
// still a plain string prompt — the suggestion list is all the registry
// contributes at this stage; validation and expansion happen after
// resolution, in resolveMessageRefs.
type messageRefPrompter struct {
	next       Prompter
	messageIDs []string
}

func (p messageRefPrompter) Prompt(f FieldSpec) (any, bool, error) {
	if f.MessageRef {
		f.Suggestions = p.messageIDs
	}
	return p.next.Prompt(f)
}

// messageIDs lists every message id in the export, sorted, for the
// message-ref prompt's pick list.
func messageIDs(doc *xregistry.Export) []string {
	var ids []string
	for _, g := range doc.MessageGroups {
		for id := range g.Messages {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	return ids
}

// resolveMessageRefs validates each message-ref parameter's value against
// the registry and expands it into the wiring values the skeleton renders:
// the producing endpoint's channel becomes topic and pubsub, and an unset
// contract gets a suggestion derived from the payload schema's id. The
// returned records describe what was resolved, for the scaffold record.
//
// The registry is the source of truth for where a message flows, and a
// silent override in either direction would hide a real disagreement, so
// an existing topic or pubsub is handled by where it came from: identical
// is accepted; a conflicting --set is an error naming both; anything else
// (a template default, a spec.values derivation, a values file) yields to
// the registry with a note, because those layers declare conventions, not
// intent about this message. The contract is different — it is
// developer-owned (the registry names a schema document, not a type), so a
// present contract always stands and the registry only fills a gap, noted
// on stderr so the value never lands invisibly.
func resolveMessageRefs(t *Template, values map[string]any, doc *xregistry.Export, sets map[string]any, notes io.Writer) ([]SubscriptionRecord, error) {
	var subs []SubscriptionRecord
	for _, f := range messageRefFields(t) {
		raw, ok := values[f.Name]
		if !ok {
			// Optional and unanswered: no subscription to record.
			continue
		}
		ref, ok := raw.(string)
		if !ok || ref == "" {
			return nil, fmt.Errorf("parameter %q must be a message id or xid (string), got %v", f.Name, raw)
		}
		sub, err := resolveMessageRef(f.Name, ref, values, doc, sets, notes)
		if err != nil {
			return nil, err
		}
		subs = append(subs, sub)
	}
	return subs, nil
}

func resolveMessageRef(param, ref string, values map[string]any, doc *xregistry.Export, sets map[string]any, notes io.Writer) (SubscriptionRecord, error) {
	r, err := doc.ResolveMessage(ref)
	var nf *xregistry.MessageNotFoundError
	if errors.As(err, &nf) {
		return SubscriptionRecord{}, fmt.Errorf("%w\n%s", err, knownMessagesMessage(ref, doc))
	}
	if err != nil {
		// An ambiguous bare id already carries its remediation.
		return SubscriptionRecord{}, err
	}

	pubsub, topic, err := producerChannel(doc, r.Group.MessageGroupID, r.Message.Xid)
	if err != nil {
		return SubscriptionRecord{}, err
	}
	if err := injectWiringValue(values, KeyTopic, topic, r.Message.Xid, sets, notes); err != nil {
		return SubscriptionRecord{}, err
	}
	if err := injectWiringValue(values, KeyPubsub, pubsub, r.Message.Xid, sets, notes); err != nil {
		return SubscriptionRecord{}, err
	}

	sub := SubscriptionRecord{Parameter: param, Message: r.Message.Xid}
	if v := r.Version; v != nil && v.DataschemaXid != "" {
		if s, serr := doc.ResolveSchema(v.DataschemaXid); serr == nil {
			sub.SchemaID = s.Schema.SchemaID
			if s.Version != nil {
				sub.SchemaVersion = s.Version.VersionID
			}
			suggestContract(values, s.Schema.SchemaID, notes)
		}
	}
	return sub, nil
}

// injectWiringValue sets a wiring value from the registry. An identical
// value already present is accepted. A conflicting one is an error when it
// came from --set — the user stated intent about this message — and a
// noted override otherwise, since defaults and derived values declare
// conventions the registry's fact about this message outranks.
func injectWiringValue(values map[string]any, key, want, messageXid string, sets map[string]any, notes io.Writer) error {
	existing, ok := values[key]
	if !ok || existing == nil || existing == "" {
		values[key] = want
		return nil
	}
	if s, _ := existing.(string); s == want {
		return nil
	}
	if _, explicit := sets[key]; explicit {
		return fmt.Errorf("%s: the registry declares %q for %s, but the values set %q\nchange --set %s= to match the registry, or fix the registry's channel", key, want, messageXid, existing, key)
	}
	values[key] = want
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (from the message registry; was %q)\n", key, want, existing)
	}
	return nil
}

// suggestContract fills an unset contract parameter with a name derived
// from the schema id. The registry names a schema document, not a type, so
// this is a suggestion — a contract the developer already set always
// stands, and the fill is noted so it never lands invisibly.
func suggestContract(values map[string]any, schemaID string, notes io.Writer) {
	if existing, ok := values[KeyContract]; ok && existing != nil && existing != "" {
		return
	}
	suggestion := SuggestContractName(schemaID)
	if suggestion == "" {
		return
	}
	values[KeyContract] = suggestion
	if notes != nil {
		fmt.Fprintf(notes, "%s: %s (suggested from the message schema; override with --set %s=<value>)\n", KeyContract, suggestion, KeyContract)
	}
}

// SuggestContractName derives a type name from a schema id: the version
// suffix is stripped and the kebab-case remainder is Pascal-cased
// ("product-export.v1" → "ProductExport"). It is a prompt-time suggestion,
// not a guarantee — no type by this name exists until it is written or
// generated, which is why the developer can always override it.
func SuggestContractName(schemaID string) string {
	base := schemaID
	if i := strings.LastIndex(base, ".v"); i > 0 && allDigits(base[i+2:]) {
		base = base[:i]
	}
	var b strings.Builder
	for _, part := range strings.Split(base, "-") {
		if part == "" {
			continue
		}
		b.WriteString(strings.ToUpper(part[:1]))
		b.WriteString(part[1:])
	}
	return b.String()
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// producerChannel resolves where a message group's messages flow: the
// channel of the producing endpoint. Several producers publish the same
// group's messages on their own channels; the sorted-first one is the
// deterministic pick until the registry grows a way to declare the
// canonical channel.
func producerChannel(doc *xregistry.Export, groupXid, messageXid string) (pubsub, topic string, err error) {
	producers := doc.ProducerEndpointsFor(groupXid)
	if len(producers) == 0 {
		return "", "", fmt.Errorf("message %s has no producer endpoint declared in the registry\ndeclare a producer endpoint for %s before scaffolding a subscriber", messageXid, groupXid)
	}
	pubsub, topic, err = xregistry.SplitChannel(producers[0].Channel)
	if err != nil {
		return "", "", fmt.Errorf("producer endpoint %s: %w", producers[0].EndpointID, err)
	}
	return pubsub, topic, nil
}

// PreviewWiring reports what resolving one registry message would inject
// at create time, without touching any values: the channel's pubsub and
// topic, and the contract name the payload schema suggests. Forms use it
// to show the routing a message pick implies before the pick is
// committed. A message without a resolvable channel yields the zero
// preview and no error — the create flow reports that properly when the
// message is actually picked.
func PreviewWiring(doc *xregistry.Export, messageID string) MessageWiring {
	r, err := doc.ResolveMessage(messageID)
	if err != nil {
		return MessageWiring{}
	}
	var w MessageWiring
	if pubsub, topic, err := producerChannel(doc, r.Group.MessageGroupID, r.Message.Xid); err == nil {
		w.Pubsub, w.Topic = pubsub, topic
	}
	if v := r.Version; v != nil && v.DataschemaXid != "" {
		if s, serr := doc.ResolveSchema(v.DataschemaXid); serr == nil {
			w.Contract = SuggestContractName(s.Schema.SchemaID)
		}
	}
	return w
}

// knownMessagesMessage builds the remediation line for an unknown message
// reference: close matches when the ref narrows the list, the full catalog
// when it does not. The registry is small enough that listing it is help,
// not noise.
func knownMessagesMessage(ref string, doc *xregistry.Export) string {
	ids := messageIDs(doc)
	var close []string
	for _, id := range ids {
		if strings.Contains(id, ref) {
			close = append(close, id)
		}
	}
	if len(close) > 0 {
		return "close matches: " + strings.Join(close, ", ")
	}
	if len(ids) > 0 {
		return "known messages: " + strings.Join(ids, ", ")
	}
	return "the registry declares no messages"
}

package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/xregistry"
)

type CreateOptions struct {
	Template   string // required; subdirectory in the templates repo holding template.yaml + skeleton/
	OutputDir  string
	Version    string
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library. Zero values target the
	// official library at integrio-intropy/intropy-templates; the CLI sets
	// them from --template-repo, INTROPY_TEMPLATE_REPO, or templateRepo in
	// the config file.
	Owner string
	Repo  string

	// Source carries the fetch seams shared by every template-fetch path.
	// GitHubBaseURL redirects the latest-release API call in tests.
	Source SourceOptions

	// OnManifest, when set, runs after the manifest loads and before
	// values resolve, render, dependency processing, or the scaffold
	// record write. A non-nil error aborts the create. Callers use it for
	// gates that must run before any output is written.
	OnManifest func(*Template) error

	// Facts, when set, feeds prompt-time parameter suggestions: what the
	// workspace's scaffold records already declare (topics, contracts,
	// ports). Facts propose to the prompter; they never resolve a value on
	// their own, and a nil index resolves exactly as before.
	Facts *WorkspaceFacts

	// RegistryURL is the base URL of the xRegistry message registry. It is
	// consulted only when the template declares a message-ref parameter
	// (x-intropy-message-ref), and mandatory only when such a parameter is
	// actually given a value: a create that wires its wiring by hand works
	// with the registry unconfigured or down. Templates without one never
	// touch it — no URL is needed and no request is made.
	RegistryURL string
}

// CreateResult is the machine-readable summary written when --output-json is
// set. It is the contract chained scaffolder steps consume; field names are
// stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`

	// Subscriptions records what each message-ref parameter resolved to
	// against the message registry; empty for templates without one.
	Subscriptions []SubscriptionRecord `json:"subscriptions,omitempty"`

	// Dependencies reports what happened to each spec.dependencies entry
	// (including transitive ones): rendered now ("created") or already
	// present ("exists").
	Dependencies []DependencyResult `json:"dependencies,omitempty"`
}

func (o *CreateOptions) applyDefaults() {
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
}

// sourceOpts projects the create options onto the shared fetch options. A
// Source that names its own Owner/Repo wins — it is the test seam.
func (o CreateOptions) sourceOpts() SourceOptions {
	s := o.Source
	s.Version = o.Version
	s.Stderr = o.Stderr
	s.UserAgent = o.UserAgent
	if s.Owner == "" && s.Repo == "" {
		s.Owner, s.Repo = libraryIdentity(o.Owner, o.Repo)
	}
	return s
}

// Create runs the full scaffold: resolve release, ensure the cached checkout,
// load manifest, resolve values (with optional interactive prompting), render.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if err := validateCreateOptions(opts); err != nil {
		return err
	}

	src, err := FetchSource(ctx, opts.sourceOpts())
	if err != nil {
		return err
	}
	tag := src.Version

	templateRoot, err := templateDir(src, src.Owner, src.Repo, opts.Template)
	if err != nil {
		return err
	}

	tmpl, values, subs, err := prepareCreateTemplate(ctx, templateRoot, opts)
	if err != nil {
		return err
	}

	if err := renderCreateOutput(filepath.Join(templateRoot, templateSkeletonDir), tmpl, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, src.Owner, src.Repo, tag, opts.Template)

	// Dependencies come from the same library checkout, so they are always
	// version-locked to the component that declared them.
	depRecords, depResults, err := processDependencies(tmpl, values, opts.OutputDir, &depContext{
		repoRoot: filepath.Dir(templateRoot),
		owner:    src.Owner,
		repo:     src.Repo,
		version:  tag,
		stderr:   opts.Stderr,
		visited:  map[string]bool{},
	}, 0)
	if err != nil {
		return err
	}

	// The template field is the repo directory name (opts.Template), not
	// tmpl.Metadata.Name — it is what a later re-fetch needs.
	if err := WriteScaffold(opts.OutputDir, Scaffold{
		SchemaVersion: ScaffoldSchemaVersion,
		Template:      opts.Template,
		Owner:         src.Owner,
		Repo:          src.Repo,
		Version:       tag,
		Values:        values,
		Role:          roleFromLabels(tmpl.Metadata.Labels),
		BlockKind:     blockKindFromLabels(tmpl.Metadata.Labels),
		DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
		DependsOn:     depRecords,
		Subscriptions: subs,
	}); err != nil {
		return err
	}

	return maybeWriteCreateResult(opts, tmpl, values, src, subs, depResults)
}

func validateCreateOptions(opts CreateOptions) error {
	if err := validateTemplateName(opts.Template); err != nil {
		return err
	}
	if opts.OutputDir == "" {
		return errors.New("--out-dir is required")
	}
	return nil
}

// prepareCreateTemplate loads the manifest and resolves values. When the
// template declares message-ref parameters it also fetches the registry
// export — once, before prompting, so the message-ref prompt can offer the
// registry's message ids — and after resolution expands the references
// into wiring values. The subscription records describe the expansion for
// the scaffold record; they are nil for templates without message refs.
func prepareCreateTemplate(ctx context.Context, templateRoot string, opts CreateOptions) (*Template, map[string]any, []SubscriptionRecord, error) {
	tmpl, err := LoadTemplate(filepath.Join(templateRoot, templateManifestName))
	if err != nil {
		return nil, nil, nil, err
	}
	if opts.OnManifest != nil {
		if err := opts.OnManifest(tmpl); err != nil {
			return nil, nil, nil, err
		}
	}

	prompter := selectPrompter(&opts)
	refs := messageRefFields(tmpl)

	// The registry export feeds two things: the message-ref prompt's pick
	// list, and the validation and expansion of any reference given. Only
	// the second is mandatory — a create that wires its topic by hand must
	// work with the registry down or unconfigured, so a fetch failure is a
	// warning and a missing URL is silence until a reference is actually
	// used; resolution below turns that into the hard error.
	var export *xregistry.Export
	var fetchErr error
	if len(refs) > 0 && opts.RegistryURL != "" {
		export, fetchErr = fetchMessageRegistry(ctx, opts)
		switch {
		case fetchErr != nil:
			if opts.Stderr != nil {
				fmt.Fprintf(opts.Stderr, "warning: message registry unavailable; subscription suggestions are off (%v)\n", fetchErr)
			}
		case prompter != nil:
			prompter = messageRefPrompter{next: prompter, messageIDs: messageIDs(export)}
		}
	}

	values, err := ResolveWith(tmpl, ResolveOptions{
		Facts:    opts.Facts,
		Files:    opts.Files,
		Stdin:    opts.Stdin,
		Sets:     opts.SetValues,
		Prompter: prompter,
		Notes:    opts.Stderr,
	})
	if err != nil {
		return nil, nil, nil, err
	}
	if len(refs) == 0 {
		return tmpl, values, nil, nil
	}
	if export == nil {
		if !messageRefValuePresent(refs, values) {
			return tmpl, values, nil, nil
		}
		if fetchErr != nil {
			return nil, nil, nil, fetchErr
		}
		return nil, nil, nil, errNoRegistryConfigured
	}
	subs, err := resolveMessageRefs(tmpl, values, export, opts.SetValues, opts.Stderr)
	if err != nil {
		return nil, nil, nil, err
	}
	return tmpl, values, subs, nil
}

// renderCreateOutput renders an extracted skeleton into outputDir, honoring
// the manifest's spec.files rules. The caller passes the skeleton root
// itself (PrepareCreate has already verified it), so the missing-skeleton
// check lives next to the fetch that could produce it.
func renderCreateOutput(skelRoot string, tmpl *Template, templateName, outputDir string, force bool, values map[string]any) error {
	if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
		return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
	}
	if err := ensureOutputDir(outputDir, force); err != nil {
		return err
	}
	return RenderFiltered(skelRoot, outputDir, values, tmpl.Spec.Files)
}

func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, src *Source, subs []SubscriptionRecord, deps []DependencyResult) error {
	if opts.OutputJSON == "" {
		return nil
	}

	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:      tmpl.Metadata.Name,
		Owner:         src.Owner,
		Repo:          src.Repo,
		Version:       src.Version,
		OutputDir:     absOut,
		Values:        values,
		Subscriptions: subs,
		Dependencies:  deps,
	}
	if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
	data, err := json.MarshalIndent(r, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	if path == "-" {
		_, err := stdout.Write(data)
		return err
	}
	return os.WriteFile(path, data, 0o644)
}

func ensureOutputDir(dir string, force bool) error {
	info, err := os.Stat(dir)
	switch {
	case errors.Is(err, os.ErrNotExist):
		return os.MkdirAll(dir, 0o755)
	case err != nil:
		return err
	case !info.IsDir():
		return fmt.Errorf("--output %s exists and is not a directory", dir)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	if len(entries) > 0 && !force {
		return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
	}
	return nil
}

// ValidateTemplateName reports whether name is safe to use as a template
// directory — the exported half of validateTemplateName for callers that
// resolve a library themselves (the dashboard's template endpoints) and need
// the same refusal before joining user input into a path.
func ValidateTemplateName(name string) error {
	return validateTemplateName(name)
}

// validateTemplateName rejects empty names and anything that could escape the
// library checkout root via filepath.Join (separators, parent refs, hidden
// directories). The template argument is user input that we turn directly into
// a path segment, so it has to be sanitized.
func validateTemplateName(name string) error {
	if name == "" {
		return errors.New("template name is required")
	}
	if name == "." || name == ".." || strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid template name %q", name)
	}
	if strings.ContainsAny(name, `/\`) {
		return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
	}
	return nil
}

func selectPrompter(opts *CreateOptions) Prompter {
	return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
}

// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
// noInput is false and stdin is a real terminal. In CI / piped contexts it
// returns nil, so Resolve reports a clean "missing required parameter(s)"
// error instead of hanging on a read.
func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
	if noInput {
		return nil
	}
	f, ok := stdin.(*os.File)
	if !ok || !isTerminal(f.Fd()) {
		return nil
	}
	return NewStdinPrompter(stdin, out)
}

package template

import (
	"bufio"
	"fmt"
	"io"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/term"
)

// Prompter resolves one missing required field with the user. The
// applied result reports whether a field Suggestion produced the value
// (shown default accepted, or a list pick) as opposed to the user typing
// it fresh. Resolution re-derives candidates after every answer
// regardless; the flag exists for prompters and callers that distinguish
// a confirmation from a novel entry.
type Prompter interface {
	Prompt(field FieldSpec) (value any, applied bool, err error)
}

// StdinPrompter is a line-based prompter. Enums render as a numbered list;
// every other type flows through one read-coerce-validate-retry loop.
// Invalid input re-prompts; EOF aborts.
//
// Suggestions change the rendering, never the authority: one suggestion
// becomes the shown default (Enter accepts, typing overrides), several
// render as a numbered list that still accepts a fresh value. Only an
// accepted or picked suggestion is reported applied.
type StdinPrompter struct {
	in      io.Reader
	out     io.Writer
	scanner *bufio.Scanner
}

func NewStdinPrompter(in io.Reader, out io.Writer) *StdinPrompter {
	return &StdinPrompter{in: in, out: out, scanner: bufio.NewScanner(in)}
}

func (p *StdinPrompter) Prompt(f FieldSpec) (any, bool, error) {
	if len(f.Suggestions) > 0 && len(f.Enum) == 0 {
		return p.promptSuggested(f)
	}
	if len(f.Enum) > 0 {
		v, err := p.promptEnum(f)
		return v, false, err
	}
	v, err := p.promptScalar(f)
	return v, false, err
}

// promptSuggested handles a scalar field with workspace-derived
// candidates. A single candidate is the prompt default; several render as
// a pick list that stays open — a scaffold's whole point may be a topic
// nobody has declared yet, so the list never replaces free input.
func (p *StdinPrompter) promptSuggested(f FieldSpec) (any, bool, error) {
	if len(f.Suggestions) == 1 {
		v, err := p.promptScalar(withDefault(f, f.Suggestions[0]))
		if err != nil {
			return nil, false, err
		}
		if s, ok := v.(string); ok && s == f.Suggestions[0] {
			return v, true, nil
		}
		return v, false, nil
	}
	return p.promptSuggestedList(f)
}

// promptSuggestedList renders candidates as a numbered list plus a
// free-text escape, reusing the enum prompt's read-validate-retry loop
// with two differences: input that matches no candidate is a new value,
// not an error, and an optional field accepts Enter as a skip — the
// message-ref prompt's "wire it by hand instead" escape, where validation
// downstream decides whether what remains is enough.
func (p *StdinPrompter) promptSuggestedList(f FieldSpec) (any, bool, error) {
	p.writeHeading(f)
	for i, s := range f.Suggestions {
		fmt.Fprintf(p.out, "  %d) %s\n", i+1, s)
	}
	if f.Required {
		fmt.Fprintln(p.out, "  or type a new value")
	} else {
		fmt.Fprintln(p.out, "  or type a new value; Enter skips")
	}
	for {
		fmt.Fprint(p.out, ": ")
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, false, err
		}
		if !ok {
			return nil, false, io.EOF
		}
		if raw == "" {
			if !f.Required {
				return f.Default, false, nil
			}
			fmt.Fprintln(p.out, "  ! please choose one")
			continue
		}
		if n, err := strconv.Atoi(raw); err == nil && n >= 1 && n <= len(f.Suggestions) {
			return coerce(f.Suggestions[n-1], f.Type), true, nil
		}
		for _, s := range f.Suggestions {
			if raw == s {
				return coerce(s, f.Type), true, nil
			}
		}
		v := coerce(raw, f.Type)
		if err := p.validateScalar(f, v); err != nil {
			fmt.Fprintf(p.out, "  ! %s\n", err)
			continue
		}
		return v, false, nil
	}
}

func (p *StdinPrompter) promptScalar(f FieldSpec) (any, error) {
	for {
		p.writeLabel(f)
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, err
		}
		if !ok {
			return nil, io.EOF
		}
		if raw == "" {
			return f.Default, nil
		}
		v := coerce(raw, f.Type)
		if err := p.validateScalar(f, v); err != nil {
			fmt.Fprintf(p.out, "  ! %s\n", err)
			continue
		}
		return v, nil
	}
}

// validateScalar is the retry-condition half of promptScalar, shared with
// the free-text path of a suggestion list: typed fields must parse, and a
// declared pattern must match.
func (p *StdinPrompter) validateScalar(f FieldSpec, v any) error {
	if isTypedField(f.Type) {
		if _, stillStr := v.(string); stillStr {
			return fmt.Errorf("%v is not a valid %s", v, f.Type)
		}
	}
	if f.Pattern != "" {
		re, err := regexp.Compile(f.Pattern)
		if err != nil {
			return fmt.Errorf("invalid pattern for %q: %w", f.Name, err)
		}
		s, ok := v.(string)
		if !ok || !re.MatchString(s) {
			return fmt.Errorf("value must match %s", f.Pattern)
		}
	}
	return nil
}

func (p *StdinPrompter) promptEnum(f FieldSpec) (any, error) {
	p.writeHeading(f)
	options := make([]string, 0, len(f.Enum))
	for i, e := range f.Enum {
		s := fmt.Sprint(e)
		options = append(options, s)
		fmt.Fprintf(p.out, "  %d) %s\n", i+1, s)
	}
	defStr, hasDef := f.Default.(string)
	for {
		if hasDef {
			fmt.Fprintf(p.out, "[%s]: ", defStr)
		} else {
			fmt.Fprint(p.out, ": ")
		}
		raw, ok, err := p.readLine()
		if err != nil {
			return nil, err
		}
		if !ok {
			return nil, io.EOF
		}
		if raw == "" {
			if hasDef {
				return coerce(defStr, f.Type), nil
			}
			fmt.Fprintln(p.out, "  ! please choose one")
			continue
		}
		if n, err := strconv.Atoi(raw); err == nil && n >= 1 && n <= len(options) {
			return coerce(options[n-1], f.Type), nil
		}
		for _, o := range options {
			if o == raw {
				return coerce(o, f.Type), nil
			}
		}
		fmt.Fprintf(p.out, "  ! %q is not one of the options\n", raw)
	}
}

func (p *StdinPrompter) writeLabel(f FieldSpec) {
	label := f.Name
	if f.Title != "" {
		label = f.Title
	}
	if f.Description != "" {
		label = fmt.Sprintf("%s (%s)", label, f.Description)
	}
	switch d := f.Default.(type) {
	case bool:
		if d {
			label += " [Y/n]"
		} else {
			label += " [y/N]"
		}
	case nil:
		if f.Type == "boolean" {
			label += " [y/n]"
		}
	default:
		label = fmt.Sprintf("%s [%v]", label, d)
	}
	fmt.Fprintf(p.out, "%s: ", label)
}

func (p *StdinPrompter) writeHeading(f FieldSpec) {
	title := f.Name
	if f.Title != "" {
		title = f.Title
	}
	if f.Description != "" {
		fmt.Fprintf(p.out, "%s (%s)\n", title, f.Description)
	} else {
		fmt.Fprintln(p.out, title)
	}
}

func (p *StdinPrompter) readLine() (string, bool, error) {
	if !p.scanner.Scan() {
		if err := p.scanner.Err(); err != nil {
			return "", false, err
		}
		return "", false, nil
	}
	return strings.TrimSpace(p.scanner.Text()), true, nil
}

// withDefault returns a copy of the field whose shown default is the
// suggestion. The schema default already lost the bracket when suggestions
// were computed (Suggest drops candidates equal to it), so overwriting is
// safe for the prompt's lifetime.
func withDefault(f FieldSpec, suggestion string) FieldSpec {
	f.Default = suggestion
	return f
}

func isTypedField(typ string) bool {
	return typ == "boolean" || typ == "integer" || typ == "number"
}

// coerce parses a string into the type declared by a JSON Schema property.
// Returns the original string if parsing fails — JSON Schema validation
// downstream produces a clean type error in that case.
func coerce(s, typ string) any {
	switch typ {
	case "boolean":
		switch strings.ToLower(s) {
		case "y", "yes", "true", "1":
			return true
		case "n", "no", "false", "0":
			return false
		}
	case "integer":
		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
			return i
		}
	case "number":
		if v, err := strconv.ParseFloat(s, 64); err == nil {
			return v
		}
	}
	return s
}

func isTerminal(fd uintptr) bool {
	return term.IsTerminal(int(fd))
}

package template

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"text/template"

	"github.com/Masterminds/sprig/v3"
	"github.com/santhosh-tekuri/jsonschema/v5"
	"gopkg.in/yaml.v3"
)

// StdinValuesPath is the sentinel a caller may pass in the values-file list
// to signal "read a single values document from this reader". It mirrors the
// `-f -` idiom used by helm, kubectl, and curl.
const StdinValuesPath = "-"

// Resolve produces the final value map by layering, in order:
//
//	defaults declared in spec.parameters.properties[*].default
//	--values files (in supplied order; "-" reads one doc from stdin)
//	--set flags (string values, coerced to declared JSON Schema types)
//	prompts for required parameters still missing (when prompter != nil)
//
// stdin is consumed at most once across the files list; passing "-" twice is
// an error. The merged map is then validated against the JSON Schema in
// spec.parameters. Finally, every entry in spec.values is rendered as a Go
// text/template (with sprig) against the merged map and added under its key.
// A spec.values key that collides with a parameter name is rejected.
func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveLayered is Resolve with an extra base layer that sits between the
// spec.parameters defaults and the --values files. Callers use it to seed
// values from an earlier resolution (e.g. a committed scaffold record) so
// they take effect without re-prompting but still yield to explicit
// --values / --set input.
func ResolveLayered(t *Template, base map[string]any, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
	return ResolveWith(t, ResolveOptions{Base: base, Files: files, Stdin: stdin, Sets: sets, Prompter: prompter})
}

// ResolveOptions is the full input to value resolution. The zero value is
// a bare resolve: schema defaults, then nothing else. Each field names one
// layer or instrument, in the order resolution applies them — Base under
// Files under Sets, Facts informing prefill and prompts, Prompter and
// Notes as the interactive and diagnostic surfaces.
type ResolveOptions struct {
	// Base sits between the schema defaults and the values files. Callers
	// seed it from an earlier resolution (e.g. a committed scaffold record)
	// so it takes effect without re-prompting but yields to explicit input.
	Base map[string]any

	// Facts is the workspace's declared wiring. It changes resolution in
	// two deliberate ways, both overridable with --set/--values:
	//
	//   - prefill: a required parameter with exactly one workspace
	//     candidate resolves to it without prompting, behaving like an
	//     optional parameter with a workspace-derived default. Each
	//     prefill is noted on Notes so the value never lands invisibly.
	//   - prompt suggestions: a parameter with several candidates prompts
	//     with them as a pick list; the prompter's confirmation is the
	//     value.
	//
	// A nil facts index resolves exactly as ResolveLayered always has.
	Facts *WorkspaceFacts

	// Files are --values files in supplied order; "-" reads one document
	// from Stdin (consumed at most once).
	Files []string
	Stdin io.Reader

	// Sets are --set flag values, applied last of the input layers.
	Sets map[string]any

	// Prompter resolves required parameters still missing after every
	// input layer; nil turns a miss into the missing-parameter error.
	Prompter Prompter

	// Notes receives one line per prefilled value — typically stderr. Nil
	// silences the notes, not the prefill.
	Notes io.Writer
}

// ResolveWith is the resolution all of Resolve, ResolveLayered, and the
// create flows share: the input layers in declaration order, prefill and
// prompts for what they leave open, then schema validation and derived
// values.
func ResolveWith(t *Template, opts ResolveOptions) (map[string]any, error) {
	fields := t.Fields()
	byName := indexFields(fields)
	out := map[string]any{}

	applyDefaultValues(fields, out)
	for k, v := range opts.Base {
		out[k] = coerceKnownFieldValue(k, v, byName)
	}
	if err := applyValuesFiles(opts.Files, opts.Stdin, out, byName); err != nil {
		return nil, err
	}
	applySetValues(opts.Sets, out, byName)
	prefill, _ := candidatesByArity(fields, out, opts.Facts)
	applyPrefill(fields, out, prefill, opts.Notes)
	if err := promptForMissingRequired(fields, out, opts.Facts, opts.Prompter); err != nil {
		return nil, err
	}
	if err := promptForMessageRefs(fields, out, opts.Prompter); err != nil {
		return nil, err
	}
	if err := validateSchema(t.Spec.Parameters, out); err != nil {
		return nil, fmt.Errorf("parameter validation: %w", err)
	}
	if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
		return nil, err
	}

	return out, nil
}

// candidatesByArity computes every open required parameter's workspace
// candidates once and splits them by what they imply: exactly one
// candidate is a prefill pick, several are prompt suggestions. Fields
// already valued — by default, base, --values, or --set — have neither.
// The single computation keeps prefill and prompts reading one snapshot,
// so the two paths can never disagree about what the workspace offers.
func candidatesByArity(fields []FieldSpec, values map[string]any, facts *WorkspaceFacts) (prefill, suggestions map[string][]string) {
	open := make([]FieldSpec, 0, len(fields))
	for _, f := range fields {
		if !f.Required {
			continue
		}
		if v, ok := values[f.Name]; ok && !isEmpty(v) {
			continue
		}
		open = append(open, f)
	}

	}
	prefill = map[string][]string{}
	suggestions = map[string][]string{}
	for name, candidates := range Suggest(open, facts, values) {
		if len(candidates) == 1 {
			prefill[name] = candidates
		} else {
			suggestions[name] = candidates
		}
	}
	return prefill, suggestions
}

// applyPrefill resolves the single-candidate picks candidatesByArity
// separated, chaining as it goes: a prefilled topic constrains contract's
// candidates to that topic's contract, so a workspace with one topic
// resolves the whole wiring without a prompt. Each prefill is noted so
// the value never lands invisibly.
func applyPrefill(fields []FieldSpec, values map[string]any, prefill map[string][]string, notes io.Writer) {
	for _, f := range fields {
		candidates, ok := prefill[f.Name]
		if !ok {
			continue
		}
		if v, valued := values[f.Name]; valued && !isEmpty(v) {
			continue
		}
		values[f.Name] = candidates[0]
		if notes != nil {
			fmt.Fprintf(notes, "%s: %s (from workspace; override with --set %s=<value>)\n", f.Name, candidates[0], f.Name)
		}
	}
}

func applyDefaultValues(fields []FieldSpec, values map[string]any) {
	for _, f := range fields {
		if f.Default != nil {
			values[f.Name] = f.Default
		}
	}
}

func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
	stdinUsed := false
	for _, path := range files {
		if path == StdinValuesPath {
			if stdinUsed {
				return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
			}
			if stdin == nil {
				return fmt.Errorf("--values - specified but no stdin reader provided")
			}
			data, err := io.ReadAll(stdin)
			if err != nil {
				return fmt.Errorf("read values from stdin: %w", err)
			}
			if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
				return err
			}
			stdinUsed = true
			continue
		}
		if err := mergeValuesFile(path, values, byName); err != nil {
			return err
		}
	}
	return nil
}

