func TestCreateResolvesMessageRef(t *testing.T) {
	lib := newSubscriberLibrary(t, "v1.0.0")
	registry := messageRegistryServer(t)
	outDir := filepath.Join(t.TempDir(), "out")
	var stderr bytes.Buffer

	err := Create(context.Background(), CreateOptions{
		Template:    "subscriber",
		OutputDir:   outDir,
		Version:     "v1.0.0",
		SetValues:   map[string]any{"name": "loader", "subscription": "io.intropy.maxbo.product.export"},
		NoInput:     true,
		Stderr:      &stderr,
		Source:      lib.sourceOpts(t.TempDir(), nil),
		RegistryURL: registry.URL,
	})
	if err != nil {
		t.Fatalf("Create: %v\nstderr: %s", err, stderr.String())
	}

	rendered, err := os.ReadFile(filepath.Join(outDir, "wiring.txt"))
	if err != nil {
		t.Fatal(err)
	}
	want := "topic=sbt-test-product-extractor-001 pubsub=product-distribution-pubsub contract=ProductExport"
	if !strings.Contains(string(rendered), want) {
		t.Errorf("rendered wiring = %q, want it to contain %q", rendered, want)
	}

	scaffold := readScaffoldT(t, outDir)
	if len(scaffold.Subscriptions) != 1 {
		t.Fatalf("subscriptions = %+v", scaffold.Subscriptions)
	}
	sub := scaffold.Subscriptions[0]
	if sub.Parameter != "subscription" {
		t.Errorf("parameter = %q", sub.Parameter)
	}
	if sub.Message != "/messagegroups/io.intropy.maxbo.product/messages/io.intropy.maxbo.product.export" {
		t.Errorf("message = %q", sub.Message)
	}
	if sub.SchemaID != "product-export.v1" || sub.SchemaVersion != "1" {
		t.Errorf("schema = %q @ %q", sub.SchemaID, sub.SchemaVersion)
	}
	// The resolved values are what system assembly later reads back.
	if got := scaffold.Values["topic"]; got != "sbt-test-product-extractor-001" {
		t.Errorf("scaffold topic = %v", got)
	}

	// The contract suggestion is noted, never invisible.
	if !strings.Contains(stderr.String(), "contract: ProductExport") {
		t.Errorf("stderr should note the contract suggestion, got %q", stderr.String())
	}
}

