func TestProbeAnyOfErrShape(t *testing.T) {
	tmpl := probeTemplate()
	err := validateSchema(tmpl.Spec.Parameters, map[string]any{"name": "svc"})
	var ve *jsonschema.ValidationError
	if !asVE(err, &ve) {
		t.Fatalf("not a ValidationError: %T %v", err, err)
