func asVE(err error, out **jsonschema.ValidationError) bool {
	if v, ok := err.(*jsonschema.ValidationError); ok {
		*out = v
		return true
	}
	type unwrapper interface{ Unwrap() error }
	if u, ok := err.(unwrapper); ok {
		return asVE(u.Unwrap(), out)
	}
	return false
}

func dump(t *testing.T, e *jsonschema.ValidationError, depth int) {
	t.Logf("%*sloc=%q abs=%q msg=%q", depth*2, "", e.InstanceLocation, e.AbsoluteKeywordLocation, e.Message)
	for _, c := range e.Causes {
		dump(t, c, depth+1)
	}
	_ = fmt.Sprint()
}
