// rewriteAnyOfFailure restates a failed top-level anyOf as the choice the
// template author encoded. The library's own text names schema pointers
// ("anyOf/0/required") and lists what each branch is missing, which reads
// as several unrelated failures rather than one unmade choice; the schema
// itself still holds the combinations, so they are what the reader gets.
// Any other failure passes through — those name the offending parameter.
func rewriteAnyOfFailure(schema map[string]any, err error) error {
	var ve *jsonschema.ValidationError
	if !errors.As(err, &ve) || !hasAnyOfCause(ve) {
		return err
