+		}
+	}
+	return false
+}
+
+// requiredCombinations lists each anyOf branch's required parameters as one
+// phrase ("topic and contract"), in declaration order. A branch that
+// requires nothing, or requires something other than a list of names,
+// yields no combinations at all — the rewrite is only an improvement when
+// it can name every alternative.
+func requiredCombinations(schema map[string]any) []string {
+	branches, ok := schema["anyOf"].([]any)
+	if !ok {
+		return nil
+	}
+	combos := make([]string, 0, len(branches))
+	for _, b := range branches {
+		branch, ok := b.(map[string]any)
+		if !ok {
+			return nil
+		}
+		required, ok := branch["required"].([]any)
+		if !ok || len(required) == 0 {
+			return nil
+		}
+		names := make([]string, 0, len(required))
+		for _, r := range required {
+			name, ok := r.(string)
+			if !ok {
+				return nil
+			}
+			names = append(names, name)
+		}
+		combos = append(combos, joinAnd(names))
+	}
+	return combos
+}
+
+// joinAnd renders a parameter list as prose: "topic and contract", "a, b
+// and c". Commas alone would blur into the ", or " separating the
+// alternatives.
+func joinAnd(names []string) string {
+	switch len(names) {
+	case 1:
+		return names[0]
+	case 2:
+		return names[0] + " and " + names[1]
+	default:
+		return strings.Join(names[:len(names)-1], ", ") + " and " + names[len(names)-1]
+	}
 }

